-- 单条语句均为「逐行整值 UPDATE」，互相独立，可单独回滚。
--
-- ⚠️ 定界符写法：值必须**紧贴** $mig$，形式为 `= $mig$<值>$mig$`，换行只能出现在定界符**之外**。
--    教训（2026-09-17 实测踩过）：写成 `= $mig$\n<值>\n$mig$` 会把首尾两个换行
--    **一起写进字段值**，导致 81 + 73 + 23 行的值被污染（虽不影响 JSON 解析，但属于非预期变更）。
-- ====================================================================

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ZXREPORTNOZX AS 征信报告记录号最新,\n    i.ZXREPORTNOSQ AS 征信报告记录号上期,\n    i.ZXREPORTNOSX AS 征信报告记录号授信,\n    i.ID AS ID,\n    i.EDUCATION AS 学历,\n    i.GUARANTORNAME AS 担保人,\n    i.GUARANTORTYPE AS 担保人类型,\n    i.ISSTATEOWNED AS 是否国有担保,\n    i.INPUTTIME AS 入库时间,\n    i.GUARANTORID AS 担保人客户编号,\n    i.SUBJECTTYPE AS 主体类型,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    c.isTechCompany AS 是否科创企业,\n    c.actualController AS 实际控制人,\n    CASE\n        WHEN c.actualController IS NOT NULL\n             AND POSITION(i.GUARANTORNAME IN c.actualController) > 0\n        THEN '是'\n        ELSE '否'\n    END AS 担保人是否是实控人,\n    u.creditSum AS 授信金额,\n    i.REPORTNO AS 报告编号\nFROM APP_GUARANTOR_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON i.customerid = c.customerId\n    AND i.customername = c.customerName\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.reportno = u.reportNo\n    AND i.customerid = u.customerId\n    AND i.customername = u.customername\nWHERE i.reportno = :reportNo\n  AND i.customername = :entName\n  AND i.guarantorname= :guarantorName","paramData":[{"id":"a91d40f8-c3cf-4c27-d73e-dbbe285a567d","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"2a99a756-74a6-70de-0f45-8a3e5071c7e8","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"987a7d66-787c-728d-c214-a3e0085b5fac","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '202609031712181';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID,\n    i.REPORTNO,\n    i.CUSTOMERID,\n    i.CUSTOMERNAME,\n    u.creditSum AS 授信金额,\n    i.QUERYTIME,\n    TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') AS \"当前时间\",\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS \"最新一期征信查询时间距当前时间天数\",\n    i.ZXREPORTNO,\n    i.EXPIREDATE,\n    i.OVERDUETOTAL,\n    i.ATTENTIONCREDITBAL,\n    i.BADCREDITBAL,\n    i.ATTENTIONGUARANTEEBAL,\n    i.BADGUARANTEEBAL,\n    i.GUARANTEEOVERDUETOTAL,\n    i.GUARANTEEATTENTIONBAL,\n    i.GUARANTEEBADBAL,\n    i.EXTENDDEBTBAL,\n    i.RESTRUCTUREDEBTBAL,\n    i.RENEWDEBTBAL,\n    i.TRANSFERDEBTBAL,\n    i.NEWOLDDEBTBAL,\n    i.NONBANKLIABTOTAL,\n    i.NONBANKHIGHRATELOAN,\n    i.INPUTTIME,\n    i.SUBJECTTYPE,\n    i.GUARANTORID,\n    i.GUARANTORNAME,\n    i.NONBANKGUARANTEEBAL,\n    i.WORKINGCAPITALLOANBAL,\n    i.WORKINGCAPITALLOAN1YBAL,\n    i.LOANBANKORGCOUNT,\n    i.GUARANTEEBANKORGCOUNT,\n    i.CREDITSHORTTERMDIFF,\n    i.CREDITLONGTERMDIFF,\n    i.CREDITDEBTDEVIATION,\n    i.GUARANTEENETASSET,\n    i.GUARANTEEBALANCEEXBANK,\n    i.SHORTTERMLOANORGCOUNT,\n    i.MIDLONGTERMLOANORGCOUNT,\n    i.REVOLVINGOVERDRAFTORGCOUNT,\n    i.DISCOUNTORGCOUNT,\n    i.BANKACCEPTANCEBILLORGCOUNT,\n    i.LETTEROFCREDITORGCOUNT,\n    i.BANKGUARANTEEORGCOUNT,\n    i.OTHERGUARANTEETRADEORGCOUNT,\n    i.SHORTTERMLOANBAL,\n    i.MIDLONGTERMLOANBAL,\n    i.REVOLVINGOVERDRAFTBAL,\n    i.DISCOUNTBAL,\n    i.BANKACCEPTANCEBILLBAL,\n    i.LETTEROFCREDITBAL,\n    i.BANKGUARANTEEBAL,\n    i.OTHERGUARANTEETRADEBAL\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\nLEFT JOIN APP_CREDIT_USE_INFO u\n    ON i.REPORTNO = u.REPORTNO\n    AND i.CUSTOMERID = u.CUSTOMERID\n    AND i.CUSTOMERNAME = u.CUSTOMERNAME\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName","paramData":[{"id":"45b00f5a-ba9a-28b9-86eb-8cd38120e4e1","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"b362361f-6e31-fb0c-3b0d-c64b452b89ec","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"fdf026be-ed28-ee8b-93cf-961245bb4dc2","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '20260903195039160';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n\n    i.ID AS ID,\n\n    i.REPORTNO AS 报告编号,\n\n    i.CUSTOMERID AS 客户编号,\n\n    i.CUSTOMERNAME AS 客户名称,\n\n    i.GUARANTORNAME AS 担保人,\n\n    i.QUERYTIME AS 征信查询时间,\n\n    i.ZXREPORTNO AS 征信报告记录号,\n\n    i.TOTALLOANBAL AS 贷款余额合计,\n\n    i.OPERATELOANBAL AS 经营性贷款余额合计,\n\n    i.CONSUMELOANBAL AS 消费类贷款余额合计,\n\n    i.HOUSELOANBAL AS 住房类贷款余额合计,\n\n    i.OTHERLOANBAL AS 其他贷款余额合计,\n\n    i.TOTALLOANCOUNT AS 贷款机构数,\n\n    i.OPERATELOANCOUNT AS 经营性贷款机构数,\n\n    i.CONSUMELOANCOUNT AS 消费类贷款机构数,\n\n    i.HOUSELOANCOUNT AS 住房类贷款机构数,\n\n    i.OTHERLOANCOUNT AS 其他贷款机构数,\n\n    i.BADBAL AS 呆账余额,\n\n    i.BZCBAL AS 被追偿余额,\n\n    i.LOANCURRENTOVERDUE AS 贷款当前逾期总金额,\n\n    i.CARDCURRENTOVERDUE AS 贷记卡当前逾期总金额,\n\n    i.GUARANTEEOVERDUEAMT AS 对外担保相关还款责任当前逾期金额,\n\n    i.NONBANKGUARANTEEBAL AS 在非银机构对外担保余额,\n\n    i.NONBANKHIGHRATELOAN AS 非银机构较高利率借款推算利率最大值,\n\n    i.GUARANTEEABNORMALBAL AS 对外担保相关还款责任五级分类非正常余额,\n\n    i.EXTENDBAL AS 展期债务余额,\n\n    i.DELAYBAL AS 落实金融困等政策银行主动延期债务余额,\n\n    i.CREDITABNORMALBAL AS 未结清信贷五级分类非正常余额,\n\n    i.ACCTABNORMALBAL AS 未结清账户状态非正常余额,\n\n    i.CARDABNORMALBAL AS 未销户贷记卡账户状态非正常余额,\n\n    i.GUARANTEEHKABNORMALBAL AS 对外担保相关还款责任还款状态非正常余额,\n\n    i.CREDITUSERATE AS 信用卡使用率,\n\n    i.INPUTTIME AS 入库时间,\n\n    i.GUARANTORID AS 担保人客户编号,\n\n    i.NONBANKLIABTOTAL AS 在非银机构负债合计,\n\n    i.LOANQUERY12M AS 近一年贷款审批征信查询次数,\n\n    i.LOANQUERY6M AS 近6个月贷款审批征信查询次数,\n\n    i.CARDQUERY6M AS 近6个月信用卡审批征信查询次数,\n\n    i.LOANQUERY3M AS 近3个月贷款审批征信查询次数,\n\n    i.CARDQUERY12M AS 近一年信用卡审批征信查询次数,\n\n    i.CARDQUERY3M AS 近3个月信用卡审批征信查询次数,\n\n    i.SELFQUERY1M AS 近1个月本人查询征信查询次数,\n\n    CURRENT_DATE - CAST(i.QUERYTIME AS DATE) AS 最新一期征信查询时间距当前时间天数\n\nFROM APP_GUARANTOR_CREDIT_INFO i\n\nINNER JOIN APP_GUARANTOR_INFO g\n\n    ON i.ZXREPORTNO = g.ZXREPORTNOZX\n\nWHERE g.reportno = :reportNo\n\n  AND g.customername = :entName\n\n  AND g.guarantorname = :guarantorName","paramData":[{"id":"5ff1afc1-152f-3f24-67ee-