UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    r.REPORTNO AS 报告编号,\n    r.CUSTOMERID AS 客户编号,\n    r.CUSTOMERNAME AS 客户名称,\n    c.CLRNAME AS 押品名称,\n    r.PLEDGESERIALNO AS 不动产登记编号,\n    r.PLEDGEENAME AS 他项权姓名,\n    r.GUARANTEESCOPE AS 担保范围,\n    r.PLEDGETYPENAME AS 抵押方式,\n    r.MAXCREDITORAMT AS 债权数额,\n    r.STARTEND AS 债务履行期限,\n    r.REGISTERTIMESTAMP AS 设定日期,\n    r.INPUTTIME AS 入库时间,\n    r.CLRID AS 押品编号\nFROM APP_COLLATERAL_MORTGAGE_INFO r\nLEFT JOIN APP_COLLATERAL_INFO c\n    ON r.CLRID = c.CLRID\n    AND r.REPORTNO = c.REPORTNO\n    AND r.CUSTOMERID = c.CUSTOMERID\n    AND r.CUSTOMERNAME = c.CUSTOMERNAME\nWHERE r.REPORTNO = :reportNo\n  AND r.CUSTOMERNAME = :entName","paramData":[{"id":"86acf60b-e659-3dc4-0da4-f7eb1504bb62","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"2b9d1dae-163a-6ab5-8ab7-e7735e89c0b0","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
