UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID,\n    i.REPORTNO,\n    i.CUSTOMERID,\n    i.CUSTOMERNAME,\n    i.FROZENAMOUNT,\n    i.DEBITSAMENAMETRANSFERRATIO,\n    i.CREDITSAMENAMETRANSFERRATIO,\n    i.YEARAVGDEPOSIT,\n    i.LASTYEARAVGDEPOSIT,\n    i.PROPERTYINCOME,\n    i.PROPERTYINCOMEYOY,\n    i.PROPERTYINCOMESUPERVISED,\n    i.ELECTRICFEEINCOME,\n    i.ELECTRICFEEYOY,\n    i.ELECTRICFEESUPERVISED,\n    i.KEYWORDCOUNTERPARTYCREDITAMOUNT,\n    i.KEYWORDREMARKCREDITAMOUNT,\n    i.INPUTTIME\nFROM APP_SETTLE_ASSET_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"ee7c14df-4130-bf5a-1564-b0afa52af762","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"e6710754-a470-f9ff-2705-da94adc715a7","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
