UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.SUSPECTEDLOANPURPOSEABNORMAL AS 贷款用途疑似异常,\n    i.ID AS id,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.INPUTTIME AS 入库时间,\n    i.SUSPECTEDFUNDRETURN AS 疑似资金回流,\n    i.SUSPECTEDBORROWEDNAMELOAN AS 疑似借名贷款,\n    i.SUSPECTEDSHELLCOMPANY AS 疑似空壳公司,\n    i.SUSPECTEDGUARANTEECIRCLE AS 疑似担保圈链,\n    i.INTRABANKRELATION AS 行内关联关系,\n    i.ENTRUSTEDPAYMANYTOONE AS 受托支付多对一,\n    i.COLLATERALSAMECOMMUNITY AS 抵押物同小区关联\nFROM APP_GRAPH_HIT_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.CUSTOMERNAME = :entName","paramData":[{"id":"d955d75f-2a27-8981-abcf-7f7595dceb6a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"24b04b99-8238-e3b4-94c1-93005b8a5893","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
