UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    -- 剔除我行对外担保最新值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保最新值,\n\n    -- 剔除我行对外担保授信值\n    MAX(\n        CASE\n            WHEN i.ZXREPORTNO = g.zxReportNoSX\n            THEN i.GUARANTEEBALANCEEXBANK\n        END\n    ) AS 剔除我行对外担保授信值,\n\n    -- 剔除我行对外担保较授信增长率\n    CASE\n        WHEN MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) IS NULL\n        OR MAX(\n            CASE\n                WHEN i.ZXREPORTNO = g.zxReportNoSX\n                THEN i.GUARANTEEBALANCEEXBANK\n            END\n        ) = 0\n        THEN NULL\n\n        ELSE\n            (\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.ZXREPORTNOZX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n                -\n                MAX(\n                    CASE\n                        WHEN i.ZXREPORTNO = g.zxReportNoSX\n                        THEN i.GUARANTEEBALANCEEXBANK\n                    END\n                )\n            )\n            /\n            MAX(\n                CASE\n                    WHEN i.ZXREPORTNO = g.zxReportNoSX\n                    THEN i.GUARANTEEBALANCEEXBANK\n                END\n            )\n            * 100\n    END AS 剔除我行对外担保较授信增长率\n\nFROM APP_CREDIT_REPORT_INFO i\nINNER JOIN APP_GUARANTOR_INFO g\n    ON i.ZXREPORTNO IN (g.ZXREPORTNOZX, g.zxReportNoSX)\nWHERE g.reportno = :reportNo\n  AND g.customername = :entName\n  AND g.guarantorname = :guarantorName","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'泰州公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2095833592136478721';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    COALESCE(x.CUSTOMERID, g.CUSTOMERID) AS 客户编号,\n    COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) AS 客户名称,\n    COALESCE(x.NAME, g.NAME) AS 股东名称,\n    x.NAME AS 信贷股东名称,\n    g.NAME AS 工商股东名称,\n    CASE\n        WHEN x.NAME IS NULL THEN '工商有、信贷无'\n        WHEN g.NAME IS NULL THEN '信贷有、工商无'\n    END AS 对比结果\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName\nAND (x.NAME IS NULL OR g.NAME IS NULL)","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2097286270184075265';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN COUNT(CASE WHEN x.NAME IS NULL OR g.NAME IS NULL THEN 1 END) > 0 THEN '否'\n        ELSE '是'\n    END AS 股东是否一致\nFROM APP_XD_SHAREHOLDER_INFO x\nFULL OUTER JOIN APP_SHAREHOLDER_INFO g\n    ON x.CUSTOMERID = g.CUSTOMERID\n    AND x.NAME = g.NAME\nWHERE COALESCE(x.REPORTNO, g.REPORTNO) = :reportNo\nAND COALESCE(x.CUSTOMERNAME, g.CUSTOMERNAME) = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
