UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.LEGALPERSON AS 信贷系统法人,\n    i.ICLEGALPERSON AS 外部工商法人,\n    CASE\n        WHEN c.LEGALPERSON = i.ICLEGALPERSON THEN '是'\n        ELSE '否'\n    END AS 是否一致\nFROM APP_CUSTOMER_INFO c\nLEFT JOIN APP_IC_INFO i\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2097290064745738241';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.CREDITDATE AS 授信日期,\n    s.ICSHAREHOLDERNAME AS 股东名称,\n    s.icStockNum AS 持股数,\n    s.icAmount AS 投资金额,\n    s.CHANGETIME AS 变更时间,\n    s.PERCENTBEFORE AS 变更前持股比例,\n    s.PERCENTAFTER AS 变更后持股比例,\n    g.IS_STATE_OWNED AS 是否国有,\n    CASE\n        WHEN s.PERCENTBEFORE < 20 AND s.PERCENTAFTER >= 20\n            THEN '新增'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER < 20\n            THEN '退出'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER > s.PERCENTBEFORE\n            THEN '上升'\n        WHEN s.PERCENTBEFORE >= 20 AND s.PERCENTAFTER >= 20\n             AND s.PERCENTAFTER < s.PERCENTBEFORE\n            THEN '下降'\n        ELSE '其他'\n    END AS 变更类型\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2097298221127708674';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN COUNT(*) > 0 THEN '是'\n        ELSE '否'\n    END AS 是否存在重要股东变更\nFROM APP_CREDIT_USE_INFO c\nINNER JOIN APP_IC_SHAREHOLDER_INFO s\n    ON c.CUSTOMERID = s.CUSTOMERID\nLEFT JOIN APP_SHAREHOLDER_INFO g\n    ON s.CUSTOMERID = g.CUSTOMERID\n    AND s.ICSHAREHOLDERNAME = g.NAME\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName\nAND s.CHANGETIME > c.CREDITDATE\nAND (\n    s.PERCENTBEFORE >= 20\n    OR s.PERCENTAFTER >= 20\n)\nAND s.PERCENTBEFORE <> s.PERCENTAFTER","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2097301442667753473';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n\n    -- 1、借款人是否假冒国企\n    CASE\n        WHEN i.ISFAKESTATEOWNED = '是' THEN '是'\n        ELSE '否'\n    END AS 借款人是否假冒国企,\n\n    -- 2、是否有股东假冒国企\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_SHAREHOLDER_INFO s\n            WHERE s.CUSTOMERID = i.CUSTOMERID\n              AND s.IS_FAKE_STATE_OWNED = '是'\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 是否有股东假冒国企,\n\n    -- 3、假冒国企的股东名称\n    (\n        SELECT LISTAGG(s.NAME, '、')\n               WITHIN GROUP (ORDER BY s.NAME)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.CUSTOMERID = i.CUSTOMERID\n          AND s.IS_FAKE_STATE_OWNED = '是'\n    ) AS 假冒国企股东名称\n\nFROM APP_IC_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
