UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.productBelongName AS 组合产品名称,\n    SUM(i.BALANCE) AS 借据余额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN ('正常结清', '提前结清', '逾期结清', '理赔结清')\nGROUP BY i.productBelongName","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
