UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    COUNT(CASE\n        WHEN i.LOANCHANGERPTCOUNTS > 0 THEN 1\n    END) AS 还款方式变更借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.LOANCHANGERPTCOUNTS > 0 THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 还款方式变更借据余额,\n\n    COUNT(CASE\n        WHEN i.ISEXTEND = '是' THEN 1\n    END) AS 展期借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.ISEXTEND = '是' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 展期借据余额,\n\n    COUNT(CASE\n        WHEN i.ISRESTRUCTED = '是' THEN 1\n    END) AS 重组借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.ISRESTRUCTED = '是' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 重组借据余额,\n\n    COUNT(CASE\n        WHEN i.OCCURTYPE = '借新还旧' THEN 1\n    END) AS 借新还旧借据数量,\n    COALESCE(SUM(CASE\n        WHEN i.OCCURTYPE = '借新还旧' THEN i.BALANCE\n        ELSE 0\n    END), 0) AS 借新还旧借据余额\n\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN ('正常结清', '提前结清', '逾期结清', '理赔结清')","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2097609822494011393';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.NEXTPAYDATE AS 下一还款日期,\n    i.PAYPRINCIPALAMT AS 应还本金,\n    i.REPAYMENTPERIOD AS 还款周期,\n    i.BUSINESSRATE AS 执行利率\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.FIXEDASSETLOAN = '是'\nAND i.LOANSTATUS NOT IN ('正常结清', '提前结清', '逾期结清', '理赔结清')\nORDER BY i.NEXTPAYDATE ASC\nLIMIT 1","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
