UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    ROUND(\n        ABS(\n            EXTRACT(\n                EPOCH FROM (\n                    i.PAYEECANCELDATE::DATE - CURRENT_DATE\n                )\n            )\n        ) / 86400 / 30,\n        1\n    ) AS 受托支付对象注销距当前日期月数\nFROM APP_ENTRUST_PAY_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.PAYEECANCELDATE IS NOT NULL\nAND i.PAYEECANCELDATE::DATE <= CURRENT_DATE\nORDER BY ABS(i.PAYEECANCELDATE::DATE - CURRENT_DATE)\nLIMIT 1","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
