UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND countMom < 0 THEN 1 END) = 3\n        THEN '是'\n        ELSE '否'\n    END AS 代发人数连续三期逐步减少,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND amountMom < 0 THEN 1 END) = 3\n        THEN '是'\n        ELSE '否'\n    END AS 代发金额连续三期逐步减少,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND countYoy < 0 THEN 1 END) = 3\n        THEN '是'\n        ELSE '否'\n    END AS 连续三期代发人数同比下降,\n\n    CASE\n        WHEN COUNT(*) >= 3\n         AND COUNT(CASE WHEN rn <= 3 AND amountYoy < 0 THEN 1 END) = 3\n        THEN '是'\n        ELSE '否'\n    END AS 连续三期代发金额同比下降\nFROM (\n    SELECT\n        i.STATMONTH AS statMonth,\n        i.COUNTMOM AS countMom,\n        i.AMOUNTMOM AS amountMom,\n        i.COUNTYOY AS countYoy,\n        i.AMOUNTYOY AS amountYoy,\n        ROW_NUMBER() OVER (\n            ORDER BY i.STATMONTH DESC\n        ) AS rn\n    FROM APP_PAYROLL_STAT_INFO i\n    WHERE i.REPORTNO = :reportNo\n    AND i.CUSTOMERNAME = :entName\n) t\nWHERE rn <= 3","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098076921578401793';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.SUPPLIER AS 前五大上下游名称,\ni.SUPPLIERTYPENAME AS 客户类型\nFROM APP_TOP_FIVE_UPDOWN_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.SUPPLIERTYPENAME IN ('前五大上游', '前五大下游')","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098246233404485633';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = '前五大上游'\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = '借方'\n                   AND s.RANKNO IN (\n                       'TOP1', 'TOP2', 'TOP3', 'TOP4', 'TOP5',\n                       'TOP6', 'TOP7', 'TOP8', 'TOP9', 'TOP10'\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = '前五大上游'\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大上游与借方前十大匹配率,\n\n    ROUND(\n        COUNT(DISTINCT CASE\n            WHEN u.SUPPLIERTYPENAME = '前五大下游'\n             AND u.SUPPLIER IS NOT NULL\n             AND EXISTS (\n                 SELECT 1\n                 FROM APP_SETTLE_COUNTERPARTY_INFO s\n                 WHERE s.REPORTNO = u.REPORTNO\n                   AND s.CUSTOMERID = u.CUSTOMERID\n                   AND s.CUSTOMERNAME = u.CUSTOMERNAME\n                   AND s.DIRECTION = '贷方'\n                   AND s.RANKNO IN (\n                       'TOP1', 'TOP2', 'TOP3', 'TOP4', 'TOP5',\n                       'TOP6', 'TOP7', 'TOP8', 'TOP9', 'TOP10'\n                   )\n                   AND s.COUNTERPARTYNAME = u.SUPPLIER\n             )\n            THEN u.SUPPLIER\n        END) * 100.0\n        / NULLIF(\n            COUNT(DISTINCT CASE\n                WHEN u.SUPPLIERTYPENAME = '前五大下游'\n                THEN u.SUPPLIER\n            END),\n            0\n        ),\n        2\n    ) AS 前五大下游与贷方前十大匹配率\nFROM APP_TOP_FIVE_UPDOWN_INFO u\nWHERE u.REPORTNO = :reportNo\nAND u.CUSTOMERNAME = :entName\nAND u.SUPPLIERTYPENAME IN ('前五大上游', '前五大下游')","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098255255243337730';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.COUNTERPARTYNAME AS 交易对手名称,\n    i.DIRECTION AS 方向,\n    i.AMOUNT AS 发生额（万元）,\n    i.RANKNO AS 排名\nFROM APP_SETTLE_COUNTERPARTY_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098272869793411074';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.ACCOUNTNO AS 账号,\n    i.ACCOUNTSTATUS AS 账户状态,\n    i.ACCOUNTBALANCE AS 账户余额（万元）,\n    i.SUPERVISEFLAG AS 监管标识,\n    i.INPUTTIME AS 入库时间\nFROM APP_SETTLE_ACCOUNT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName","paramData":[{"id":"38a09880-39f7-bfed-a329-5f81d64fd4f6","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"4333b0d6-3a4d-bea5-20e3-5923ba7e1c1a","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098297608888922113';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.SUBJECTTYPE AS 主体类型,\n    i.SUBJECTNAME AS 主体名称,\n    i.eventTypeOrder AS 舆情事件排序,\n    CASE\n        WHEN i.SUBJECTTYPE = '借款人' THEN c.ISLISTEDCOMPANY\n        WHEN i.SUBJECTTYPE = '股东' THEN s.IS_QUOTED\n    END AS 是否上市,\n    CASE\n        WHEN i.SUBJECTTYPE = '股东' THEN s.STOCK_PERCENT\n    END AS 持股比例,\n    i.EVENTTIME AS 舆情发生时间,\n    i.EVENTTYPE AS 舆情类型,\n    i.EVENTDESC AS 舆情事件描述,\n    i.INPUTTIME AS 入库时间\nFROM APP_REPUTATION_EVENT_INFO i\nLEFT JOIN APP_CUSTOMER_INFO c\n    ON c.REPORTNO = i.REPORTNO\n    AND c.CUSTOMERID = i.CUSTOMERID\n    AND c.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = '借款人'\n    AND i.SUBJECTNAME = c.CUSTOMERNAME\nLEFT JOIN APP_SHAREHOLDER_INFO s\n    ON s.REPORTNO = i.REPORTNO\n    AND s.CUSTOMERID = i.CUSTOMERID\n    AND s.CUSTOMERNAME = i.CUSTOMERNAME\n    AND i.SUBJECTTYPE = '股东'\n    AND i.SUBJECTNAME = s.NAME\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.EVENTTYPE IN (\n    '证券市场违规问题',\n    '企业股票戴帽',\n    '企业有退市风险',\n    '企业评级被下调',\n    '企业高管无法履职',\n    '财务造假'\n)\nAND (\n    (\n        i.SUBJECTTYPE = '借款人'\n        AND c.ISLISTEDCOMPANY = '是'\n    )\n    OR\n    (\n        i.SUBJECTTYPE = '股东'\n        AND s.IS_QUOTED = '是'\n    )\n)","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098316981716398082';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = '借款人'\n              AND r.SUBJECTNAME = c.CUSTOMERNAME\n              AND r.EVENTTYPE IN (\n                  '证券市场违规问题',\n                  '企业股票戴帽',\n                  '企业有退市风险',\n                  '企业评级被下调',\n                  '企业高管无法履职',\n                  '财务造假'\n              )\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 借款人是否有重大舆情,\n\n    CASE\n        WHEN EXISTS (\n            SELECT 1\n            FROM APP_REPUTATION_EVENT_INFO r\n            INNER JOIN APP_SHAREHOLDER_INFO s\n                ON s.REPORTNO = r.REPORTNO\n                AND s.CUSTOMERID = r.CUSTOMERID\n                AND s.CUSTOMERNAME = r.CUSTOMERNAME\n                AND s.NAME = r.SUBJECTNAME\n            WHERE r.REPORTNO = c.REPORTNO\n              AND r.CUSTOMERID = c.CUSTOMERID\n              AND r.CUSTOMERNAME = c.CUSTOMERNAME\n              AND r.SUBJECTTYPE = '股东'\n              AND s.IS_QUOTED = '是'\n              AND r.EVENTTYPE IN (\n                  '证券市场违规问题',\n                  '企业股票戴帽',\n                  '企业有退市风险',\n                  '企业评级被下调',\n                  '企业高管无法履职',\n                  '财务造假'\n              )\n        )\n        THEN '是'\n        ELSE '否'\n    END AS 上市股东是否有重大舆情,\n\n    COALESCE((\n        SELECT SUM(s.STOCK_PERCENT)\n        FROM APP_SHAREHOLDER_INFO s\n        WHERE s.REPORTNO = c.REPORTNO\n          AND s.CUSTOMERID = c.CUSTOMERID\n          AND s.CUSTOMERNAME = c.CUSTOMERNAME\n          AND s.IS_QUOTED = '是'\n    ), 0) AS 上市股东持股比例合计\n\nFROM APP_CUSTOMER_INFO c\nWHERE c.REPORTNO = :reportNo\nAND c.CUSTOMERNAME = :entName","paramData":[{"id":"aaa66566-dbcc-e75c-fb3a-daecfeaa2200","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"fb2fd6b5-b1f5-ffbc-e170-ed7d91551643","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2098322971241230338';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.FINREPORTNO AS 财报编号,\n    i.ACCOUNTMONTH AS 会计月,\n    i.REPORTSCOPE AS 报表口径,\n    i.REPORTPERIOD AS 报表周期,\n    i.AUDITFLAG AS 是否审计,\n    i.CURRENCY AS 报表币种,\n    i.MONETARYUNIT AS 货币单位,\n    i.REPORTSTATUSNAME AS 报表状态中文,\n    i.REPORTSTATUS AS 报表状态码值,\n    i.INPUTTIME AS 入库时间,\n    i.REPORTTYPENO AS 报表类型,\n    i.REPORTTYPENAME AS 报表类型名称,\n    i.REVENUE AS 营业收入,\n    i.REVENUEYOY AS 营业收入同比,\n    i.NETPROFIT AS 净利润,\n    i.NETPROFITYOY AS 净利润同比,\n    i.PAIDINCAPITAL AS 实收资本,\n    i.TOTALEQUITY AS 所有者权益合计,\n    i.ACCOUNTSRECEIVABLE AS 应收账款,\n    i.ARCHANGEFROMYEARSTART AS 应收账款较年初变动,\n    i.ARCHANGEFROMYEARSTARTRATE AS 应收账款较年初增幅,\n    i.OTHERRECEIVABLE AS 其他应收款,\n    i.ORCHANGEFROMYEARSTART AS 其他应收款较年初变动,\n    i.ORCHANGEFROMYEARSTARTRATE AS 其他应收款较年初增幅,\n    i.ARORTOTALASSETRATIO AS 应收账款和其他应收款合计占总资产比例,\n    i.SHORTLOAN AS 短期借款,\n    i.SHORTLOANCHANGEFROMYEARSTART AS 短期借款较年初变动,\n    i.SHORTLOANCHANGEFROMYEARSTARTRATE AS 短期借款较年初增幅,\n    i.LONGLOAN AS 长期借款,\n    i.LONGLOANCHANGEFROMYEARSTART AS 长期借款较年初变动,\n    i.LONGLOANCHANGEFROMYEARSTARTRATE AS 长期借款较年初增幅,\n    i.LONGLOANDUEWITHIN1Y AS 一年内到期的长期借款,\n    i.SALESLOANRATIO AS 销贷比,\n    i.NOTESPAYABLE AS 应付票据,\n    i.NOTESPAYABLECHANGEFROMYEARSTART AS 应付票据较年初变动,\n    i.NOTESPAYABLECHANGEFROMYEARSTARTRATE AS 应付票据较年初增幅,\n    i.OTHERPAYABLE AS 其他应付款,\n    i.OTHERPAYABLECHANGEFROMYEARSTART AS 其他应付款较年初变动,\n    i.OTHERPAYABLECHANGEFROMYEARSTARTRATE AS 其他应付款较年初增幅,\n    i.SLTOTALLOANYOY AS 短期借款和长期借款合计同比,\n    i.ARYOY AS 应收账款同比,\n    i.ARTURNOVERDAYS AS 应收账款周转天数,\n    i.INVENTORYTURNOVERDAYS AS 存货周转天数,\n    i.INVENTORYYOY AS 存货同比,\n    i.ACCOUNTSPAYABLE AS 应付账款,\n    i.INVENTORY AS 存货,\n    i.DEBTRATIO AS 资产负债率,\n    i.SALESPROFITRATIO AS 销售利率,\n    i.NETPROFITRATIO AS 净利率\nFROM APP_FINANCE_INDICATOR_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.C