UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    t.ID AS ID,\n    t.REPORTNO AS 报告编号,\n    t.CUSTOMERID AS 客户编号,\n    t.CUSTOMERNAME AS 客户名称,\n    t.TAXPERIOD AS 纳税期,\n    t.MONTHLYTAXSALES AS 每月纳税销售额,\n    t.TOTALSALESTAX AS 当年纳税销售额累计,\n    t.YOYCHANGE AS 当年销售额较上年同期变动额,\n    t.YOYRATE AS 当年销售额较上年同期同比,\n    '最新一期' AS 时间类型,\n    f.REVENUE AS 营业收入,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE),\n        2\n    ) AS 纳税申报销售总额与当期报表相差金额,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE)\n        / NULLIF(f.REVENUE, 0) * 100,\n        2\n    ) AS 纳税申报销售总额与当期报表相差幅度\nFROM APP_GS_TAX_SALES_INFO t\nCROSS JOIN (\n    SELECT\n        MAX(ACCOUNTMONTH) AS MAX_MONTH\n    FROM APP_FINANCE_INDICATOR_INFO\n    WHERE REPORTNO = :reportNo\n    AND CUSTOMERNAME = :entName\n) m\nLEFT JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = t.REPORTNO\n    AND f.CUSTOMERID = t.CUSTOMERID\n    AND f.CUSTOMERNAME = t.CUSTOMERNAME\n    AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n    AND f.ACCOUNTMONTH = t.TAXPERIOD\nWHERE t.REPORTNO = :reportNo\nAND t.CUSTOMERNAME = :entName\nAND t.TAXPERIOD = m.MAX_MONTH","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099387836944887810';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    t.ID AS ID,\n    t.REPORTNO AS 报告编号,\n    t.CUSTOMERID AS 客户编号,\n    t.CUSTOMERNAME AS 客户名称,\n    t.INPUTTIME AS 入库时间,\n    t.TAXPERIOD AS 纳税期,\n    t.MONTHLYTAXSALES AS 每月纳税销售额,\n    t.TOTALSALESTAX AS 当年纳税销售额累计,\n    t.YOYCHANGE AS 当年销售额较上年同期变动额,\n    t.YOYRATE AS 当年销售额较上年同期同比,\n    '上年12月' AS 时间类型,\n    f.REVENUE AS 营业收入,\n  ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE),\n        2\n    ) AS 纳税申报销售总额与当期报表相差金额,\n    ROUND(\n        ABS(t.TOTALSALESTAX - f.REVENUE)\n        / NULLIF(f.REVENUE, 0) * 100,\n        2\n    ) AS 纳税申报销售总额与当期报表相差幅度\nFROM APP_GS_TAX_SALES_INFO t\nCROSS JOIN (\n    SELECT\n        MAX(ACCOUNTMONTH) AS MAX_MONTH\n    FROM APP_FINANCE_INDICATOR_INFO\n    WHERE REPORTNO = :reportNo\n    AND CUSTOMERNAME = :entName\n) m\nLEFT JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = t.REPORTNO\n    AND f.CUSTOMERID = t.CUSTOMERID\n    AND f.CUSTOMERNAME = t.CUSTOMERNAME\n    AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n    AND f.ACCOUNTMONTH = t.TAXPERIOD\nWHERE t.REPORTNO = :reportNo\nAND t.CUSTOMERNAME = :entName\nAND t.TAXPERIOD = (m.MAX_MONTH - (m.MAX_MONTH % 100)) - 88\n  AND f.REPORTPERIOD = '年报'","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099391513457864705';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    SUM(i.BALANCE) AS 非项目贷款借据余额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN ('正常结清', '提前结清', '逾期结清', '理赔结清')\nand i.PRODUCTNAME not in ('基本建设项目贷款','技术改造项目贷款','并购项目贷款','其他类项目贷款','经营性物业贷款','房地产开发贷款','土地储备开发贷款','开发区开发贷款','法人购房贷款','汽车法人按揭','设备法人按揭','其他法人按揭')","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099466901378838530';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    SUM(i.BUSINESSSUM) AS 归还股东借款金额\nFROM APP_LOAN_RECEIPT_INFO i\nWHERE i.REPORTNO = :reportNo\nAND i.CUSTOMERNAME = :entName\nAND i.LOANSTATUS NOT IN ('正常结清', '提前结清', '逾期结清', '理赔结清')\nand i.purposeName like '%归还股东借款%'","paramData":[{"id":"9cc31f8b-c0ce-4fbd-bab0-40613d884008","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"cfe523ee-9c4e-4fe4-165e-89fc654715dd","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099468248912244738';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.FINREPORTNO AS 财报编号,\n    i.ACCOUNTMONTH AS 会计月,\n    i.REPORTSCOPE AS 报表口径,\n    i.REPORTPERIOD AS 报表周期,\n    i.AUDITFLAG AS 是否审计,\n    i.CURRENCY AS 报表币种,\n    i.MONETARYUNIT AS 货币单位,\n    i.REPORTSTATUSNAME AS 报表状态中文,\n    i.REPORTSTATUS AS 报表状态码值,\n    i.INPUTTIME AS 入库时间,\n    i.REPORTTYPENO AS 报表类型,\n    i.REPORTTYPENAME AS 报表类型名称,\n    i.REVENUE AS 营业收入,\n    i.REVENUEYOY AS 营业收入同比,\n    i.NETPROFIT AS 净利润,\n    i.NETPROFITYOY AS 净利润同比,\n    i.PAIDINCAPITAL AS 实收资本,\n    i.TOTALEQUITY AS 所有者权益合计,\n    i.ACCOUNTSRECEIVABLE AS 应收账款,\n    i.ARCHANGEFROMYEARSTART AS 应收账款较年初变动,\n    i.ARCHANGEFROMYEARSTARTRATE AS 应收账款较年初增幅,\n    i.OTHERRECEIVABLE AS 其他应收款,\n    i.ORCHANGEFROMYEARSTART AS 其他应收款较年初变动,\n    i.ORCHANGEFROMYEARSTARTRATE AS 其他应收款较年初增幅,\n    i.ARORTOTALASSETRATIO AS 应收账款和其他应收款合计占总资产比例,\n    i.SHORTLOAN AS 短期借款,\n    i.SHORTLOANCHANGEFROMYEARSTART AS 短期借款较年初变动,\n    i.SHORTLOANCHANGEFROMYEARSTARTRATE AS 短期借款较年初增幅,\n    i.LONGLOAN AS 长期借款,\n    i.LONGLOANCHANGEFROMYEARSTART AS 长期借款较年初变动,\n    i.LONGLOANCHANGEFROMYEARSTARTRATE AS 长期借款较年初增幅,\n    i.LONGLOANDUEWITHIN1Y AS 一年内到期的长期借款,\n    i.SALESLOANRATIO AS 销贷比,\n    i.NOTESPAYABLE AS 应付票据,\n    i.NOTESPAYABLECHANGEFROMYEARSTART AS 应付票据较年初变动,\n    i.NOTESPAYABLECHANGEFROMYEARSTARTRATE AS 应付票据较年初增幅,\n    i.OTHERPAYABLE AS 其他应付款,\n    i.OTHERPAYABLECHANGEFROMYEARSTART AS 其他应付款较年初变动,\n    i.OTHERPAYABLECHANGEFROMYEARSTARTRATE AS 其他应付款较年初增幅,\n    i.SLTOTALLOANYOY AS 短期借款和长期借款合计同比,\n    i.ARYOY AS 应收账款同比,\n    i.ARTURNOVERDAYS AS 应收账款周转天数,\n    i.INVENTORYTURNOVERDAYS AS 存货周转天数,\n    i.INVENTORYYOY AS 存货同比,\n    i.ACCOUNTSPAYABLE AS 应付账款,\n    i.INVENTORY AS 存货,\n    i.DEBTRATIO AS 资产负债率,\n    i.SALESPROFITRATIO AS 销售利率,\n    i.NETPROFITRATIO AS 净利率\nFROM APP_FINANCE_INDICATOR_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.CUSTOMERNAME = :entName\n  AND i.REPORTSCOPE = '本部'\n  AND i.subjectType='借款人'\n  AND i.ACCOUNTMONTH::INTEGER = (\n      SELECT MAX(i2.ACCOUNTMONTH::INTEGER) - 100\n      FROM APP_FINANCE_INDICATOR_INFO i2\n      WHERE i2.REPORTNO = :reportNo\n        AND i2.CUSTOMERNAME = :entName\n  )\nORDER BY i.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099473094558101506';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    i.ID AS ID,\n    i.REPORTNO AS 报告编号,\n    i.CUSTOMERID AS 客户编号,\n    i.CUSTOMERNAME AS 客户名称,\n    i.FINREPORTNO AS 财报编号,\n    i.ACCOUNTMONTH AS 会计月,\n    i.REPORTSCOPE AS 报表口径,\n    i.REPORTPERIOD AS 报表周期,\n    i.AUDITFLAG AS 是否审计,\n    i.CURRENCY AS 报表币种,\n    i.MONETARYUNIT AS 货币单位,\n    i.REPORTSTATUSNAME AS 报表状态中文,\n    i.REPORTSTATUS AS 报表状态码值,\n    i.INPUTTIME AS 入库时间,\n    i.REPORTTYPENO AS 报表类型,\n    i.REPORTTYPENAME AS 报表类型名称,\n    i.REVENUE AS 营业收入,\n    i.REVENUEYOY AS 营业收入同比,\n    i.NETPROFIT AS 净利润,\n    i.NETPROFITYOY AS 净利润同比,\n    i.PAIDINCAPITAL AS 实收资本,\n    i.TOTALEQUITY AS 所有者权益合计,\n    i.ACCOUNTSRECEIVABLE AS 应收账款,\n    i.ARCHANGEFROMYEARSTART AS 应收账款较年初变动,\n    i.ARCHANGEFROMYEARSTARTRATE AS 应收账款较年初增幅,\n    i.OTHERRECEIVABLE AS 其他应收款,\n    i.ORCHANGEFROMYEARSTART AS 其他应收款较年初变动,\n    i.ORCHANGEFROMYEARSTARTRATE AS 其他应收款较年初增幅,\n    i.ARORTOTALASSETRATIO AS 应收账款和其他应收款合计占总资产比例,\n    i.SHORTLOAN AS 短期借款,\n    i.SHORTLOANCHANGEFROMYEARSTART AS 短期借款较年初变动,\n    i.SHORTLOANCHANGEFROMYEARSTARTRATE AS 短期借款较年初增幅,\n    i.LONGLOAN AS 长期借款,\n    i.LONGLOANCHANGEFROMYEARSTART AS 长期借款较年初变动,\n    i.LONGLOANCHANGEFROMYEARSTARTRATE AS 长期借款较年初增幅,\n    i.LONGLOANDUEWITHIN1Y AS 一年内到期的长期借款,\n    i.SALESLOANRATIO AS 销贷比,\n    i.NOTESPAYABLE AS 应付票据,\n    i.NOTESPAYABLECHANGEFROMYEARSTART AS 应付票据较年初变动,\n    i.NOTESPAYABLECHANGEFROMYEARSTARTRATE AS 应付票据较年初增幅,\n    i.OTHERPAYABLE AS 其他应付款,\n    i.OTHERPAYABLECHANGEFROMYEARSTART AS 其他应付款较年初变动,\n    i.OTHERPAYABLECHANGEFROMYEARSTARTRATE AS 其他应付款较年初增幅,\n    i.SLTOTALLOANYOY AS 短期借款和长期借款合计同比,\n    i.ARYOY AS 应收账款同比,\n    i.ARTURNOVERDAYS AS 应收账款周转天数,\n    i.INVENTORYTURNOVERDAYS AS 存货周转天数,\n    i.INVENTORYYOY AS 存货同比,\n    i.ACCOUNTSPAYABLE AS 应付账款,\n    i.INVENTORY AS 存货,\n    i.DEBTRATIO AS 资产负债率,\n    i.SALESPROFITRATIO AS 销售利率,\n    i.NETPROFITRATIO AS 净利率\nFROM APP_FINANCE_INDICATOR_INFO i\nWHERE i.REPORTNO = :reportNo\n  AND i.CUSTOMERNAME = :entName\n  AND i.REPORTSCOPE = '合并'\n  AND i.subjectType='借款人'\n  AND i.ACCOUNTMONTH::INTEGER = (\n      SELECT MAX(i2.ACCOUNTMONTH::INTEGER) - 100\n      FROM APP_FINANCE_INDICATOR_INFO i2\n      WHERE i2.REPORTNO = :reportNo\n        AND i2.CUSTOMERNAME = :entName\n  )\nORDER BY i.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
