UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.THISYEAR AS 国税最新一期日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.GFREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.GFREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.GFRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.GFRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.GFPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.GFPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.GFINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.GFINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = '本部'\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n          AND f2.subjectType='借款人'\n  )\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099486550187323393';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.LASTYEAR AS 国税去年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.LASTYEARREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.LASTYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.LASTYEARRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.LASTYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.LASTYEARPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.LASTYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.LASTYEARINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.LASTYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = '本部'\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.LASTYEAR), 1, 6)\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 1) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType='借款人'\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099487507734343681';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.BEFOREYEAR AS 国税前年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.BEFOREYEARREVENUE AS 国税营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.BEFOREYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.BEFOREYEARRECEIVABLE AS 国税应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.BEFOREYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.BEFOREYEARPAYABLE AS 国税应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.BEFOREYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.BEFOREYEARINVENTORY AS 国税存货,\n    ROUND(\n        ABS(f.INVENTORY - g.BEFOREYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GS_FINANCE_DATA_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND g.REPORTSCOPE = '本部'\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.BEFOREYEAR), 1, 6)\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 2) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType='借款人'\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099492014430105601';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.THISYEAR AS 国发最新一期日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.GFREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.GFREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.GFRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.GFRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.GFPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.GFPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.GFINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.GFINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.THISYEAR), 1, 6)\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType='借款人'\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","p