UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.BEFOREYEAR AS 国发前年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.BEFOREYEARREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.BEFOREYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.BEFOREYEARRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.BEFOREYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.BEFOREYEARPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.BEFOREYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.BEFOREYEARINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.BEFOREYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.BEFOREYEAR), 1, 6)\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 2) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType='借款人'\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099493932292386817';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    f.ACCOUNTMONTH AS 会计月,\n    g.LASTYEAR AS 国发去年日期,\n\n    f.REVENUE AS 财报营业收入,\n    g.LASTYEARREVENUE AS 国发营业收入,\n    ROUND(\n        ABS(f.REVENUE - g.LASTYEARREVENUE)\n        / NULLIF(ABS(f.REVENUE), 0) * 100,\n        2\n    ) AS 营业收入偏差幅度,\n\n    f.ACCOUNTSRECEIVABLE AS 财报应收账款,\n    g.LASTYEARRECEIVABLE AS 国发应收账款,\n    ROUND(\n        ABS(f.ACCOUNTSRECEIVABLE - g.LASTYEARRECEIVABLE)\n        / NULLIF(ABS(f.ACCOUNTSRECEIVABLE), 0) * 100,\n        2\n    ) AS 应收账款偏差幅度,\n\n    f.ACCOUNTSPAYABLE AS 财报应付账款,\n    g.LASTYEARPAYABLE AS 国发应付账款,\n    ROUND(\n        ABS(f.ACCOUNTSPAYABLE - g.LASTYEARPAYABLE)\n        / NULLIF(ABS(f.ACCOUNTSPAYABLE), 0) * 100,\n        2\n    ) AS 应付账款偏差幅度,\n\n    f.INVENTORY AS 财报存货,\n    g.LASTYEARINVENTORY AS 国发存货,\n    ROUND(\n        ABS(f.INVENTORY - g.LASTYEARINVENTORY)\n        / NULLIF(ABS(f.INVENTORY), 0) * 100,\n        2\n    ) AS 存货偏差幅度\n\nFROM APP_FINANCE_INDICATOR_INFO f\nLEFT JOIN APP_GUOFA_REPORT_INFO g\n    ON f.REPORTNO = g.REPORTNO\n    AND f.CUSTOMERID = g.CUSTOMERID\n    AND f.CUSTOMERNAME = g.CUSTOMERNAME\n    AND f.ACCOUNTMONTH = SUBSTRING(TRIM(g.LASTYEAR), 1, 6)\n\nWHERE f.REPORTNO = :reportNo\n  AND f.CUSTOMERNAME = :entName\n  AND f.REPORTSCOPE = '本部'\n  AND f.subjectType='借款人'\n  AND f.ACCOUNTMONTH::INTEGER = (\n      SELECT\n          (FLOOR(MAX(f2.ACCOUNTMONTH::INTEGER) / 100) - 1) * 100 + 12\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = :reportNo\n        AND f2.CUSTOMERNAME = :entName\n  AND f2.subjectType='借款人'\n  )\nORDER BY f.INPUTTIME DESC\nLIMIT 1","paramData":[{"id":"54b10e26-eac0-d8dd-0c52-1154a40f3c5a","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"6c7e9878-e4ba-ae73-4754-f3f5165bb750","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099494367401095170';

UPDATE index_params SET script = $mig${"dataSource":"bosz-dev-local-0001","sql":"SELECT\n    c.ID AS ID,\n    c.REPORTNO AS 报告编号,\n    c.CUSTOMERID AS 客户编号,\n    c.CUSTOMERNAME AS 客户名称,\n    c.QUERYTIME AS 征信查询时间,\n\n    f.ACCOUNTMONTH AS 会计月,\n\n    f.SHORTLOAN AS 财报短期借款,\n    c.SHORTTERMLOANBAL AS 征信短期借款未结清余额,\n    ROUND(\n        c.SHORTTERMLOANBAL - f.SHORTLOAN,\n        2\n    ) AS 征信短期借款相差,\n\n    f.LONGLOAN AS 财报长期借款,\n    f.LONGLOANDUEWITHIN1Y AS 一年内到期长期借款,\n    c.MIDLONGTERMLOANBAL AS 征信中长期借款未结清余额,\n    ROUND(\n        c.MIDLONGTERMLOANBAL\n        - COALESCE(f.LONGLOAN, 0)\n        - COALESCE(f.LONGLOANDUEWITHIN1Y, 0),\n        2\n    ) AS 征信中长期借款相差,\n\n    ROUND(\n        ABS(\n            COALESCE(c.SHORTTERMLOANBAL, 0)\n            + COALESCE(c.MIDLONGTERMLOANBAL, 0)\n            - COALESCE(f.SHORTLOAN, 0)\n            - COALESCE(f.LONGLOAN, 0)\n            - COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n        )\n        / NULLIF(\n            ABS(\n                COALESCE(f.SHORTLOAN, 0)\n                + COALESCE(f.LONGLOAN, 0)\n                + COALESCE(f.LONGLOANDUEWITHIN1Y, 0)\n            ),\n            0\n        ) * 100,\n        2\n    ) AS 征信债务偏离度,\n\n    c.GUARANTEEBALANCEEXBANK AS 对外担保余额（剔除我行）,\n    f.TOTALEQUITY AS 所有者权益,\n\n    ROUND(\n        c.GUARANTEEBALANCEEXBANK\n        / NULLIF(f.TOTALEQUITY, 0) * 100,\n        2\n    ) AS 对外担保净资产比\n\nFROM APP_CREDIT_REPORT_INFO c\n\nINNER JOIN APP_FINANCE_INDICATOR_INFO f\n    ON f.REPORTNO = c.REPORTNO\n    AND f.CUSTOMERID = c.CUSTOMERID\n    AND f.CUSTOMERNAME = c.CUSTOMERNAME\n    AND f.GUARANTORID = c.GUARANTORID\n    AND f.GUARANTORNAME = c.GUARANTORNAME\n    AND f.REPORTSCOPE = '本部'\n\nWHERE c.REPORTNO = :reportNo\n  AND c.CUSTOMERNAME = :entName\n  AND c.GUARANTORNAME = :guarantorName\n\n  AND f.ACCOUNTMONTH = (\n      SELECT MAX(f2.ACCOUNTMONTH)\n      FROM APP_FINANCE_INDICATOR_INFO f2\n      WHERE f2.REPORTNO = c.REPORTNO\n        AND f2.CUSTOMERID = c.CUSTOMERID\n        AND f2.CUSTOMERNAME = c.CUSTOMERNAME\n        AND f2.GUARANTORID = c.GUARANTORID\n        AND f2.GUARANTORNAME = c.GUARANTORNAME\n        AND f2.REPORTSCOPE = '本部'\n  )\n\n  AND c.QUERYTIME >= TO_DATE(f.ACCOUNTMONTH || '01', 'YYYYMMDD')\n  AND c.QUERYTIME < ADD_MONTHS(\n      TO_DATE(f.ACCOUNTMONTH || '01', 'YYYYMMDD'),\n      4\n  )\n\nLIMIT 1","paramData":[{"id":"2a9152b1-8542-a0db-0c17-d11b59c4d460","name":"reportNo","desc":"","type":"1","isSync":"Y","defaultValue":"'RPT-202603-001'","relateIndex":null},{"id":"bd138d27-b35d-1604-20e3-ac40f629e622","name":"entName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null},{"id":"63fa1a6a-7dec-c102-848f-8cd76318565c","name":"guarantorName","desc":"","type":"1","isSync":"Y","defaultValue":"'苏州XX精密机械制造有限公司'","relateIndex":null}],"moduleCode":"","knowledgeCode":"","knowledgeName":"","knowledgeGroupInfo":[],"withModelSummary":false,"knowledgeParamList":[{"key":"1","paramName":"entName","paramValue":"科大讯飞股份有限公司"}],"entName":"科大讯飞股份有限公司"}$mig$
WHERE paramno = '2099504086844977154';

